func verticalOrder(root *TreeNode) [][]int {
    if root == nil {
        return [][]int{}
    }

    cols := make(map[int][]int)
    type pair struct {
        node *TreeNode
        pos  int
    }
    queue := []pair{{root, 0}}

    for len(queue) > 0 {
        p := queue[0]
        queue = queue[1:]
        cols[p.pos] = append(cols[p.pos], p.node.Val)

        if p.node.Left != nil {
            queue = append(queue, pair{p.node.Left, p.pos - 1})
        }
        if p.node.Right != nil {
            queue = append(queue, pair{p.node.Right, p.pos + 1})
        }
    }

    keys := make([]int, 0, len(cols))
    for k := range cols {
        keys = append(keys, k)
    }
    sort.Ints(keys)

    res := make([][]int, len(keys))
    for i, k := range keys {
        res[i] = cols[k]
    }
    return res
}
